<div class="page-heading"><div><span class="eyebrow">MAKE IT YOURS</span><h1>Settings</h1><p>Your profile and workspace preferences.</p></div></div><?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<section class="settings-section"><div><h2>Profile</h2><p class="muted"><?= e(current_user()['email']) ?></p></div><form class="stack-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="profile"><label>Full name<input name="name" value="<?= e(current_user()['name']) ?>" maxlength="190" required autocomplete="name"></label><button class="button fit"><?= icon('check') ?>Save profile</button></form></section>
<section class="settings-section"><div><h2>Password</h2><p class="muted">Changing your password signs out other sessions.</p></div><form class="stack-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="password"><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><div class="form-grid"><label>New password<input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required><small>At least 12 characters.</small></label><label>Confirm new password<input name="password_confirmation" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label></div><button class="button fit"><?= icon('lock') ?>Update password</button></form></section>
<?php if(workspace()['role']==='owner'): ?><section class="settings-section"><div><h2>Company</h2><p class="muted">Details used on new invoices.</p></div><form class="stack-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="workspace"><div class="form-grid"><label>Company name<input name="name" value="<?= e(workspace()['name']) ?>" maxlength="190" required></label><label>Registration / tax number<input name="registration_number" value="<?= e(workspace()['registration_number']) ?>" maxlength="100"></label></div><label>Company address<textarea name="address" maxlength="2000" rows="3"><?= e(workspace()['address']) ?></textarea></label><div class="form-grid"><label>Currency<input value="<?= e(workspace()['currency']) ?>" disabled><small>Fixed for this workspace.</small></label><label>Monthly expense budget<input type="number" min="0" step="0.01" name="monthly_budget" value="<?= decimal((int)workspace()['monthly_budget']) ?>" required></label></div><button class="button fit"><?= icon('check') ?>Save company</button></form></section><?php endif ?>
<?php if(can_manage()): ?><section class="settings-section"><div><h2>Categories</h2><p class="muted">Separate categories for income and expenses.</p></div><div><div class="category-list"><?php foreach($categories as $cat): ?><span class="category-tag"><i class="swatch <?= e($cat['type']) ?>"></i><?= e($cat['name']) ?><small><?= e($cat['type']) ?></small></span><?php endforeach ?></div><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="category"><label><span class="sr-only">Category name</span><input name="name" placeholder="New category" maxlength="100" required></label><label><span class="sr-only">Category type</span><select name="type"><option value="expense">Expense</option><option value="income">Income</option></select></label><button class="icon-button" title="Add category" aria-label="Add category"><?= icon('plus') ?></button></form></div></section><?php endif ?>
<section class="settings-section"><div><h2>New workspace</h2><p class="muted">Keep another company's finances separate.</p></div><form class="stack-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="new-workspace"><div class="form-grid"><label>Company name<input name="name" maxlength="190" required></label><label>Currency<select name="currency"><option>EUR</option><option>USD</option><option>GBP</option></select></label></div><button class="button fit"><?= icon('plus') ?>Create workspace</button></form></section>
